// ============================================================
// CODE-001 – Build Context
// ============================================================
// Purpose:
// Build one unified context for the assignment engine.
//
// Sources:
//   GS-003 – Read EngineerMaster
//   GS-004 – Read WeeklyRoster
//   GS-005 – Read SupportCalendar
//
// This node DOES NOT:
//   - create engineers
//   - modify WeeklyRoster
//   - modify EngineerMaster
//   - modify SupportCalendar
//   - assign tickets
//
// It only combines the required data into one context object.
// ============================================================


// ============================================================
// 1. READ ENGINEER MASTER
// ============================================================

let engineerMasterItems = [];

try {
  engineerMasterItems =
    $("GS-003 – Read EngineerMaster").all();
} catch (error) {
  engineerMasterItems = [];
}

if (!engineerMasterItems.length) {
  throw new Error(
    "CODE-001: GS-003 – Read EngineerMaster returned no data."
  );
}


// ============================================================
// 2. READ WEEKLY ROSTER
// ============================================================

let weeklyRosterItems = [];

try {
  weeklyRosterItems =
    $("GS-004 – Read WeeklyRoster").all();
} catch (error) {
  weeklyRosterItems = [];
}

if (!weeklyRosterItems.length) {
  throw new Error(
    "CODE-001: GS-004 – Read WeeklyRoster returned no data."
  );
}


// ============================================================
// 3. READ SUPPORT CALENDAR
// ============================================================

let supportCalendarItems = [];

try {
  supportCalendarItems =
    $("GS-005 Read SupportCalendar").all();
} catch (error) {
  supportCalendarItems = [];
}

if (!supportCalendarItems.length) {
  throw new Error(
    "CODE-001: GS-005 – Read SupportCalendar returned no data."
  );
}


// ============================================================
// 4. NORMALIZE ENGINEER MASTER
// ============================================================

const engineerMaster =
  engineerMasterItems.map(item => {

    const row = item.json || {};

    return {
      ...row
    };

  });


// ============================================================
// 5. NORMALIZE WEEKLY ROSTER
// ============================================================

const weeklyRoster =
  weeklyRosterItems.map(item => {

    const row = item.json || {};

    return {
      Effective_From:
        String(row.Effective_From ?? "").trim(),

      Effective_To:
        String(row.Effective_To ?? "").trim(),

      Day:
        String(row.Day ?? "").trim(),

      Shift_ID:
        String(row.Shift_ID ?? "").trim(),

      Engineer_Name:
        String(row.Engineer_Name ?? "").trim(),

      Member_ID:
        String(row.Member_ID ?? "").trim(),

      Assignment_Level:
        String(row.Assignment_Level ?? "").trim(),

      Available:
        String(row.Available ?? "Yes").trim()
    };

  });


// ============================================================
// 6. NORMALIZE SUPPORT CALENDAR
// ============================================================

const supportCalendar =
  supportCalendarItems.map(item => {

    const row = item.json || {};

    return {

      Day:
        String(row.Day ?? "").trim(),

      Business_Start:
        String(row.Business_Start ?? "").trim(),

      Business_End:
        String(row.Business_End ?? "").trim(),

      Active_Shifts:
        String(row.Active_Shifts ?? "").trim(),

      Allowed_Levels:
        String(row.Allowed_Levels ?? "").trim(),

      Max_L1:
        Number(row.Max_L1 ?? 0),

      Max_L2:
        Number(row.Max_L2 ?? 0),

      Max_L3:
        Number(row.Max_L3 ?? 0),

      Assignment_Mode:
        String(row.Assignment_Mode ?? "").trim(),

      Timezone:
        String(row.Timezone ?? "Asia/Kolkata").trim(),

      Active:
        String(row.Active ?? "No").trim()
    };

  });


// ============================================================
// 7. CURRENT DATE / TIME
// ============================================================
//
// Use Asia/Kolkata because this is the configured timezone
// for your SupportCalendar.
// ============================================================

const now = new Date();

const currentDate =
  new Intl.DateTimeFormat(
    "en-CA",
    {
      timeZone: "Asia/Kolkata",
      year: "numeric",
      month: "2-digit",
      day: "2-digit"
    }
  ).format(now);

const currentTime =
  new Intl.DateTimeFormat(
    "en-GB",
    {
      timeZone: "Asia/Kolkata",
      hour: "2-digit",
      minute: "2-digit",
      hour12: false
    }
  ).format(now);

const currentDay =
  new Intl.DateTimeFormat(
    "en-US",
    {
      timeZone: "Asia/Kolkata",
      weekday: "long"
    }
  ).format(now);


// ============================================================
// 8. FIND TODAY'S SUPPORT CALENDAR RULE
// ============================================================

const todayCalendarRule =
  supportCalendar.find(
    row =>
      row.Day.toLowerCase() ===
      currentDay.toLowerCase()
  ) || null;


// ============================================================
// 9. DETERMINE WHETHER TODAY IS ACTIVE
// ============================================================

const todayActive =
  todayCalendarRule
    ? String(todayCalendarRule.Active)
        .trim()
        .toLowerCase() === "yes"
    : false;


// ============================================================
// 10. FIND CURRENT ROSTER PERIOD
// ============================================================
//
// A roster record is considered part of the current period
// when CurrentDate falls between Effective_From and
// Effective_To.
// ============================================================

const currentPeriodRoster =
  weeklyRoster.filter(row => {

    if (
      !row.Effective_From ||
      !row.Effective_To
    ) {
      return false;
    }

    return (
      currentDate >= row.Effective_From &&
      currentDate <= row.Effective_To
    );

  });


// ============================================================
// 11. FIND TODAY'S ROSTER
// ============================================================

const todayRoster =
  currentPeriodRoster.filter(row => {

    return (
      row.Day.toLowerCase() ===
      currentDay.toLowerCase()
    );

  });


// ============================================================
// 12. RETURN UNIFIED CONTEXT
// ============================================================

return [
  {
    json: {

      // ------------------------------------------------------
      // Workflow Context
      // ------------------------------------------------------

      WorkflowContext: {

        Timestamp:
          now.toISOString(),

        Timezone:
          "Asia/Kolkata",

        CurrentDate:
          currentDate,

        CurrentDay:
          currentDay,

        CurrentTime:
          currentTime,

        TodayActive:
          todayActive

      },


      // ------------------------------------------------------
      // Engineer Master
      // ------------------------------------------------------

      EngineerMaster:
        engineerMaster,

      EngineerMasterCount:
        engineerMaster.length,


      // ------------------------------------------------------
      // Weekly Roster
      // ------------------------------------------------------

      WeeklyRoster:
        weeklyRoster,

      WeeklyRosterCount:
        weeklyRoster.length,


      // ------------------------------------------------------
      // Current Roster Period
      // ------------------------------------------------------

      CurrentPeriodRoster:
        currentPeriodRoster,

      CurrentPeriodRosterCount:
        currentPeriodRoster.length,


      // ------------------------------------------------------
      // Today's Roster
      // ------------------------------------------------------

      TodayRoster:
        todayRoster,

      TodayRosterCount:
        todayRoster.length,


      // ------------------------------------------------------
      // Support Calendar
      // ------------------------------------------------------

      SupportCalendar:
        supportCalendar,

      SupportCalendarCount:
        supportCalendar.length,


      // ------------------------------------------------------
      // Today's Calendar Rule
      // ------------------------------------------------------

      TodayCalendarRule:
        todayCalendarRule,


      // ------------------------------------------------------
      // Status
      // ------------------------------------------------------

      Status:
        "CODE-001 OK"

    }
  }
];

// ============================================================
// CW-000A – Save Tickets
// ============================================================
// Purpose:
// Preserve each incoming ConnectWise ticket as an individual
// n8n item.
//
// IMPORTANT:
// Do NOT wrap all tickets into a single Tickets array.
// Each ticket must remain a separate item so downstream
// assignment and scheduling nodes process tickets independently.
// ============================================================

const tickets = $input.all();

return tickets.map(item => ({
  json: item.json
}));

const ctx = $('CODE-000C - Save Shifts').first().json;

return [
{
  json: {
    ...ctx,
    Engineers: $input.all()
  }
}
];

// ================================================================
// ROSTER-001 – Build WeeklyRoster
// ================================================================
//
// PURPOSE
// -------
// Convert the visual OriginalRoster Google Sheet into normalized
// WeeklyRoster records.
//
// BUSINESS RULES
// --------------
// 1. OriginalRoster = ONLY source of scheduled engineers.
// 2. EngineerMaster = used only to validate/enrich engineers.
// 3. EngineerMaster must NEVER introduce an engineer.
// 4. ShiftMaster = source of Shift_ID and shift timings.
// 5. ConnectWise In/Out is NOT used here.
// 6. CODE-003 handles live ConnectWise availability later.
// 7. If today falls inside a roster period, use that period.
// 8. If today falls between periods, use the next upcoming period.
// 9. Sunday can contain engineers only when explicitly present
//    in OriginalRoster.
//
// L1 ROTATION RULE
// ----------------
// 1. L1 S1 engineer works Monday-Friday.
// 2. The other L1 engineer is discovered from Saturday.
// 3. Saturday L1 resource works S2 on Saturday.
// 4. That same L1 resource works S3 Tuesday-Friday.
// 5. That L1 resource has Sunday + Monday OFF.
// 6. S1 L1 does NOT work Saturday.
// 7. Engineer names are never hard-coded.
// 8. The Saturday L1 engineer is discovered from actual
//    OriginalRoster.
//
// IMPORTANT
// ---------
// The L1 normalization happens AFTER OriginalRoster has been
// parsed.
//
// Level2 and Level3 records are NOT changed.
//
// ================================================================


// ---------------------------------------------------------------
// 1. INPUT
// ---------------------------------------------------------------

const originalRows =
  $input.all().map(item => item.json);

if (!originalRows.length) {
  throw new Error(
    "ROSTER-001: GS-006 returned no OriginalRoster data."
  );
}


// ---------------------------------------------------------------
// 2. CONSTANTS
// ---------------------------------------------------------------

const DAYS = [
  "Monday",
  "Tuesday",
  "Wednesday",
  "Thursday",
  "Friday",
  "Saturday",
  "Sunday"
];

const DAY_COLUMN_MAP = {

  Monday: [
    "13 July - 8 Aug",
    "col_4",
    "col_5"
  ],

  Tuesday: [
    "col_6",
    "col_7",
    "col_8"
  ],

  Wednesday: [
    "col_9",
    "col_10",
    "col_11"
  ],

  Thursday: [
    "col_12",
    "col_13",
    "col_14"
  ],

  Friday: [
    "col_15",
    "col_16",
    "col_17"
  ],

  Saturday: [
    "col_18"
  ],

  Sunday: [
    "col_19"
  ]

};


// ---------------------------------------------------------------
// 3. DATE HELPERS
// ---------------------------------------------------------------

function pad2(value) {

  return String(value)
    .padStart(2, "0");

}


function toDateOnlyUTC(date) {

  return new Date(
    Date.UTC(
      date.getUTCFullYear(),
      date.getUTCMonth(),
      date.getUTCDate()
    )
  );

}


function formatDateUTC(date) {

  return (
    date.getUTCFullYear() +
    "-" +
    pad2(date.getUTCMonth() + 1) +
    "-" +
    pad2(date.getUTCDate())
  );

}


function parseDMY(text) {

  const match =
    String(text)
      .trim()
      .match(
        /^(\d{1,2})[\/\-](\d{1,2})[\/\-](\d{4})$/
      );

  if (!match) {
    return null;
  }

  const day =
    Number(match[1]);

  const month =
    Number(match[2]);

  const year =
    Number(match[3]);

  return new Date(
    Date.UTC(
      year,
      month - 1,
      day
    )
  );

}


function parseMonthName(monthText) {

  const months = {

    jan: 0,
    january: 0,

    feb: 1,
    february: 1,

    mar: 2,
    march: 2,

    apr: 3,
    april: 3,

    may: 4,

    jun: 5,
    june: 5,

    jul: 6,
    july: 6,

    aug: 7,
    august: 7,

    sep: 8,
    sept: 8,
    september: 8,

    oct: 9,
    october: 9,

    nov: 10,
    november: 10,

    dec: 11,
    december: 11

  };

  const key =
    String(monthText)
      .trim()
      .toLowerCase();

  return Object.prototype.hasOwnProperty.call(
    months,
    key
  )
    ? months[key]
    : null;

}


// ---------------------------------------------------------------
// 4. PARSE ROSTER PERIOD
// ---------------------------------------------------------------

function parseRosterPeriod(label) {

  if (!label) {
    return null;
  }

  const text =
    String(label)
      .replace(/\u00a0/g, " ")
      .replace(/\s+/g, " ")
      .trim();

  const match =
    text.match(
      /^(\d{1,2})\s+([A-Za-z]+)\s*-\s*(\d{1,2})\s+([A-Za-z]+)$/
    );

  if (!match) {
    return null;
  }

  const startDay =
    Number(match[1]);

  const startMonth =
    parseMonthName(match[2]);

  const endDay =
    Number(match[3]);

  const endMonth =
    parseMonthName(match[4]);

  if (
    startMonth === null ||
    endMonth === null
  ) {
    return null;
  }

  const currentYear =
    new Date().getUTCFullYear();

  let startDate =
    new Date(
      Date.UTC(
        currentYear,
        startMonth,
        startDay
      )
    );

  let endDate =
    new Date(
      Date.UTC(
        currentYear,
        endMonth,
        endDay
      )
    );

  if (endDate < startDate) {

    endDate =
      new Date(
        Date.UTC(
          currentYear + 1,
          endMonth,
          endDay
        )
      );

  }

  return {

    label: text,

    startDate,

    endDate,

    startDateText:
      formatDateUTC(startDate),

    endDateText:
      formatDateUTC(endDate)

  };

}


// ---------------------------------------------------------------
// 5. FIND ALL ROSTER PERIODS
// ---------------------------------------------------------------

const detectedPeriods = [];

for (const row of originalRows) {

  for (const key of Object.keys(row)) {

    const value =
      row[key];

    if (
      typeof value !== "string" ||
      !value.trim()
    ) {
      continue;
    }

    const parsed =
      parseRosterPeriod(value);

    if (!parsed) {
      continue;
    }

    const alreadyExists =
      detectedPeriods.some(
        p =>
          p.label === parsed.label &&
          p.startDateText === parsed.startDateText &&
          p.endDateText === parsed.endDateText
      );

    if (!alreadyExists) {

      detectedPeriods.push(
        parsed
      );

    }

  }

}


if (!detectedPeriods.length) {

  throw new Error(
    "ROSTER-001: No roster period was detected in OriginalRoster."
  );

}


// ---------------------------------------------------------------
// 6. SELECT ACTIVE / NEXT ROSTER PERIOD
// ---------------------------------------------------------------

const now =
  new Date();

const currentDate =
  toDateOnlyUTC(now);

let selectedPeriod =
  detectedPeriods.find(
    period =>
      currentDate >= period.startDate &&
      currentDate <= period.endDate
  );


// If today is not inside a roster period,
// choose next upcoming period.

if (!selectedPeriod) {

  const futurePeriods =
    detectedPeriods
      .filter(
        period =>
          period.startDate > currentDate
      )
      .sort(
        (a, b) =>
          a.startDate - b.startDate
      );

  if (futurePeriods.length) {

    selectedPeriod =
      futurePeriods[0];

  }

}


// If still nothing, use most recent period.

if (!selectedPeriod) {

  selectedPeriod =
    [...detectedPeriods]
      .sort(
        (a, b) =>
          b.startDate - a.startDate
      )[0];

}


// ---------------------------------------------------------------
// 7. LOCATE PERIOD HEADER ROW
// ---------------------------------------------------------------

let periodHeaderIndex = -1;

for (
  let i = 0;
  i < originalRows.length;
  i++
) {

  const row =
    originalRows[i];

  const found =
    Object.values(row).some(
      value =>
        String(value ?? "").trim() ===
        selectedPeriod.label
    );

  if (found) {

    periodHeaderIndex =
      i;

    break;

  }

}


if (periodHeaderIndex === -1) {

  throw new Error(
    `ROSTER-001: Selected roster period "${selectedPeriod.label}" was found, but its header row could not be located.`
  );

}


// ---------------------------------------------------------------
// 8. FIND WEEKDAY HEADER ROW
// ---------------------------------------------------------------

let dayHeaderIndex = -1;

for (
  let i = periodHeaderIndex + 1;
  i < originalRows.length;
  i++
) {

  const row =
    originalRows[i];

  const values =
    Object.values(row)
      .map(
        v =>
          String(v ?? "").trim()
      );

  const dayCount =
    DAYS.filter(
      day =>
        values.includes(day)
    ).length;

  if (dayCount >= 5) {

    dayHeaderIndex =
      i;

    break;

  }

}


if (dayHeaderIndex === -1) {

  throw new Error(
    `ROSTER-001: Weekday header was not found for roster period "${selectedPeriod.label}".`
  );

}


// ---------------------------------------------------------------
// 9. GET ENGINEER MASTER
// ---------------------------------------------------------------

const ENGINEER_MASTER_NODE =
  "GS-003 – Read EngineerMaster";

let engineerMasterItems = [];

try {

  engineerMasterItems =
    $(ENGINEER_MASTER_NODE).all();

}
catch (error) {

  engineerMasterItems = [];

}


// ---------------------------------------------------------------
// 10. BUILD ENGINEER MASTER LOOKUP
// ---------------------------------------------------------------

const engineerMasterMap =
  new Map();


function normalizeName(value) {

  return String(value ?? "")
    .trim()
    .toLowerCase()
    .replace(/\s+/g, " ");

}


function normalizeMemberId(value) {

  return String(value ?? "")
    .trim()
    .toLowerCase();

}


for (const item of engineerMasterItems) {

  const row =
    item.json || {};

  const engineerName =
    row.Engineer_Name ??
    row.EngineerName ??
    row["Engineer Name"] ??
    row.name ??
    "";

  const memberId =
    row.Member_ID ??
    row.MemberID ??
    row["Member ID"] ??
    "";

  const level =
    row.Assignment_Level ??
    row.AssignmentLevel ??
    row["Assignment Level"] ??
    "";

  const active =
    row.Active ??
    "Yes";

  if (!engineerName) {
    continue;
  }

  engineerMasterMap.set(
    normalizeName(engineerName),
    {

      EngineerName:
        String(engineerName).trim(),

      MemberID:
        String(memberId).trim(),

      AssignmentLevel:
        String(level).trim(),

      Active:
        String(active).trim()

    }
  );

}


// ---------------------------------------------------------------
// 11. SHIFT MASTER
// ---------------------------------------------------------------

const SHIFT_MASTER_NODE =
  "GS-002 – Read ShiftMaster";

let shiftMasterItems = [];

try {

  shiftMasterItems =
    $(SHIFT_MASTER_NODE).all();

}
catch (error) {

  shiftMasterItems = [];

}


// ---------------------------------------------------------------
// 12. BUILD SHIFT LOOKUP
// ---------------------------------------------------------------

const shiftMap =
  new Map();


function normalizeTime(value) {

  return String(value ?? "")
    .trim()
    .toLowerCase()
    .replace(/\s+/g, " ");

}


for (const item of shiftMasterItems) {

  const row =
    item.json || {};

  const shiftId =
    row.Shift_ID ??
    row.ShiftID ??
    "";

  const start =
    row.Start_Time ??
    row.StartTime ??
    "";

  const end =
    row.End_Time ??
    row.EndTime ??
    "";

  if (!shiftId) {
    continue;
  }

  const key =
    normalizeTime(start) +
    "|" +
    normalizeTime(end);

  shiftMap.set(
    key,
    {

      Shift_ID:
        String(shiftId).trim(),

      Shift_Start:
        String(start).trim(),

      Shift_End:
        String(end).trim()

    }
  );

}


// ---------------------------------------------------------------
// 13. FALLBACK SHIFT MAP
// ---------------------------------------------------------------

const fallbackShifts = [

  {
    Shift_ID: "S1",
    Shift_Start: "8:00",
    Shift_End: "17:30"
  },

  {
    Shift_ID: "S2",
    Shift_Start: "11:00",
    Shift_End: "20:30"
  },

  {
    Shift_ID: "S3",
    Shift_Start: "12:30",
    Shift_End: "22:00"
  },

  {
    Shift_ID: "S4",
    Shift_Start: "14:30",
    Shift_End: "00:00"
  },

  {
    Shift_ID: "S5",
    Shift_Start: "17:30",
    Shift_End: "03:00"
  }

];


// ---------------------------------------------------------------
// 14. CONVERT TIMES TO MINUTES
// ---------------------------------------------------------------

function timeToMinutes(value) {

  if (!value) {
    return null;
  }

  let text =
    String(value)
      .trim()
      .toLowerCase();

  const ampmMatch =
    text.match(
      /^(\d{1,2})(?::(\d{2}))?\s*(am|pm)$/
    );

  if (ampmMatch) {

    let hour =
      Number(ampmMatch[1]);

    const minute =
      Number(ampmMatch[2] || 0);

    const ampm =
      ampmMatch[3];

    if (
      ampm === "pm" &&
      hour !== 12
    ) {
      hour += 12;
    }

    if (
      ampm === "am" &&
      hour === 12
    ) {
      hour = 0;
    }

    return (
      hour * 60 +
      minute
    );

  }

  const twentyFour =
    text.match(
      /^(\d{1,2}):(\d{2})$/
    );

  if (twentyFour) {

    return (
      Number(twentyFour[1]) * 60 +
      Number(twentyFour[2])
    );

  }

  return null;

}


// ---------------------------------------------------------------
// 15. GET SHIFT ID
// ---------------------------------------------------------------

function getShiftId(
  start,
  end
) {

  const startMin =
    timeToMinutes(start);

  const endMin =
    timeToMinutes(end);


  // First try ShiftMaster.

  for (const shift of shiftMap.values()) {

    const smStart =
      timeToMinutes(
        shift.Shift_Start
      );

    const smEnd =
      timeToMinutes(
        shift.Shift_End
      );

    if (
      smStart === startMin &&
      smEnd === endMin
    ) {

      return shift.Shift_ID;

    }

  }


  // Then fallback.

  for (const shift of fallbackShifts) {

    const smStart =
      timeToMinutes(
        shift.Shift_Start
      );

    const smEnd =
      timeToMinutes(
        shift.Shift_End
      );

    if (
      smStart === startMin &&
      smEnd === endMin
    ) {

      return shift.Shift_ID;

    }

  }

  return null;

}


// ---------------------------------------------------------------
// 16. FIND ENGINEER MASTER MATCH
// ---------------------------------------------------------------

function findEngineer(name) {

  const normalized =
    normalizeName(name);

  if (!normalized) {
    return null;
  }


  // Exact match.

  if (
    engineerMasterMap.has(
      normalized
    )
  ) {

    return engineerMasterMap.get(
      normalized
    );

  }


  // Partial/first-name matching.

  const matches = [];

  for (
    const engineer
    of engineerMasterMap.values()
  ) {

    const masterName =
      normalizeName(
        engineer.EngineerName
      );

    const firstName =
      masterName.split(" ")[0];

    if (
      normalized === firstName ||
      masterName.startsWith(
        normalized + " "
      )
    ) {

      matches.push(
        engineer
      );

    }

  }

  if (matches.length === 1) {
    return matches[0];
  }

  return null;

}


// ---------------------------------------------------------------
// 17. DETECT ROSTER DATA RANGE
// ---------------------------------------------------------------

let dataEndIndex =
  originalRows.length;

for (
  let i = dayHeaderIndex + 1;
  i < originalRows.length;
  i++
) {

  const row =
    originalRows[i];

  const isAnotherPeriod =
    Object.values(row).some(
      value => {

        const parsed =
          parseRosterPeriod(
            String(value ?? "").trim()
          );

        return (
          parsed &&
          parsed.label !==
            selectedPeriod.label
        );

      }
    );

  if (isAnotherPeriod) {

    dataEndIndex =
      i;

    break;

  }

}


// ---------------------------------------------------------------
// 18. PROCESS SHIFT GROUPS
// ---------------------------------------------------------------

const weeklyRoster = [];
const validationErrors = [];

let currentShift = null;

for (
  let i = dayHeaderIndex + 1;
  i < dataEndIndex;
  i++
) {

  const row =
    originalRows[i];

  const shiftStart =
    String(
      row["Shift Start"] ?? ""
    ).trim();

  const shiftEnd =
    String(
      row["Shift End"] ?? ""
    ).trim();


  // New shift begins.

  if (
    shiftStart &&
    shiftEnd
  ) {

    const shiftId =
      getShiftId(
        shiftStart,
        shiftEnd
      );

    if (!shiftId) {

      validationErrors.push({

        Type:
          "SHIFT_MAPPING_ERROR",

        Row:
          row.row_number ?? null,

        ShiftStart:
          shiftStart,

        ShiftEnd:
          shiftEnd,

        Message:
          "Unable to map OriginalRoster timing to ShiftMaster."

      });

    }

    currentShift = {

      Shift_ID:
        shiftId,

      Shift_Start:
        shiftStart,

      Shift_End:
        shiftEnd

    };

  }


  // No shift established yet.

  if (!currentShift) {
    continue;
  }


  // Process each day.

  for (const day of DAYS) {

    const columns =
      DAY_COLUMN_MAP[day] || [];


    for (const column of columns) {

      const rawName =
        String(
          row[column] ?? ""
        ).trim();

      if (!rawName) {
        continue;
      }


      // Ignore accidental header values.

      if (
        DAYS.includes(rawName)
      ) {
        continue;
      }


      // EngineerMaster validation.

      const engineer =
        findEngineer(rawName);

      if (!engineer) {

        validationErrors.push({

          Type:
            "UNKNOWN_ENGINEER",

          Row:
            row.row_number ?? null,

          Day:
            day,

          Shift_ID:
            currentShift.Shift_ID,

          Engineer_Name:
            rawName,

          Message:
            "Engineer exists in OriginalRoster but could not be uniquely matched in EngineerMaster."

        });

        continue;

      }


      // Active validation.

      const activeValue =
        String(
          engineer.Active ?? "Yes"
        )
          .trim()
          .toLowerCase();

      if (
        activeValue === "no" ||
        activeValue === "false" ||
        activeValue === "inactive"
      ) {

        validationErrors.push({

          Type:
            "INACTIVE_ENGINEER",

          Row:
            row.row_number ?? null,

          Day:
            day,

          Shift_ID:
            currentShift.Shift_ID,

          Engineer_Name:
            engineer.EngineerName,

          Message:
            "Engineer is present in OriginalRoster but inactive in EngineerMaster."

        });

        continue;

      }


      // Create normalized WeeklyRoster record.

      weeklyRoster.push({

        Effective_From:
          selectedPeriod.startDateText,

        Effective_To:
          selectedPeriod.endDateText,

        Day:
          day,

        Shift_ID:
          currentShift.Shift_ID,

        Shift_Start:
          currentShift.Shift_Start,

        Shift_End:
          currentShift.Shift_End,

        Engineer_Name:
          engineer.EngineerName,

        Member_ID:
          engineer.MemberID,

        Assignment_Level:
          engineer.AssignmentLevel,

        Available:
          "Yes",

        Source:
          "OriginalRoster",

        RosterPeriod:
          selectedPeriod.label

      });

    }

  }

}


// ---------------------------------------------------------------
// 19. REMOVE DUPLICATES
// ---------------------------------------------------------------

const uniqueMap =
  new Map();

for (
  const record
  of weeklyRoster
) {

  const key =
    [

      record.Effective_From,

      record.Effective_To,

      record.Day,

      record.Shift_ID,

      normalizeMemberId(
        record.Member_ID
      )

    ].join("|");


  if (!uniqueMap.has(key)) {

    uniqueMap.set(
      key,
      record
    );

  }

}

let finalRoster =
  Array.from(
    uniqueMap.values()
  );


// ===============================================================
// 20. L1 ROTATION NORMALIZATION
// ===============================================================
//
// IMPORTANT
// ---------
// The L1 engineer is NOT hard-coded.
//
// The L1 engineer actually present on Saturday in
// OriginalRoster becomes the rotating L1.
//
// ROTATING L1 SCHEDULE:
//
// Monday     = OFF
// Tuesday    = S3
// Wednesday  = S3
// Thursday   = S3
// Friday     = S3
// Saturday   = S2
// Sunday     = OFF
//
// The other L1 remains:
//
// Monday     = S1
// Tuesday    = S1
// Wednesday  = S1
// Thursday   = S1
// Friday     = S1
// Saturday   = OFF
// Sunday     = OFF
//
// ONLY LEVEL1 records are affected.
//
// LEVEL2 AND LEVEL3 ARE NOT MODIFIED.
// ===============================================================


// ---------------------------------------------------------------
// 20A. Find L1 engineers present on Saturday.
// ---------------------------------------------------------------

const saturdayL1Records =
  finalRoster.filter(
    record =>

      record.Day === "Saturday" &&

      String(
        record.Assignment_Level ?? ""
      )
        .trim()
        .toLowerCase() === "level1"
  );


// ---------------------------------------------------------------
// 20B. Identify rotating L1.
// ---------------------------------------------------------------

let rotatingL1 = null;

if (
  saturdayL1Records.length === 1
) {

  rotatingL1 =
    saturdayL1Records[0];

}
else if (
  saturdayL1Records.length > 1
) {

  validationErrors.push({

    Type:
      "MULTIPLE_L1_SATURDAY",

    Count:
      saturdayL1Records.length,

    Engineers:
      saturdayL1Records.map(
        r => r.Engineer_Name
      ),

    Message:
      "More than one Level1 engineer is scheduled on Saturday."

  });

}
else {

  validationErrors.push({

    Type:
      "NO_L1_SATURDAY",

    Message:
      "No Level1 engineer is scheduled on Saturday for this roster cycle."

  });

}


// ---------------------------------------------------------------
// 20C. Normalize rotating L1.
// ---------------------------------------------------------------
//
// Tuesday-Friday:
//     S3 = 12:30 - 22:00
//
// Saturday:
//     S2 = 11:00 - 20:30
//
// Monday/Sunday:
//     No record is created or introduced.
//
// IMPORTANT:
// We only MODIFY existing records.
// We never create a new engineer record here.
// ---------------------------------------------------------------

if (rotatingL1) {

  const rotatingMemberId =
    normalizeMemberId(
      rotatingL1.Member_ID
    );


  for (
    const record
    of finalRoster
  ) {

    // Only modify the rotating L1.

    if (
      normalizeMemberId(
        record.Member_ID
      ) !== rotatingMemberId
    ) {
      continue;
    }


    // Only Level1.

    if (
      String(
        record.Assignment_Level ?? ""
      )
        .trim()
        .toLowerCase() !== "level1"
    ) {
      continue;
    }


    // ---------------------------------------------------------
    // Tuesday-Friday = S3
    // ---------------------------------------------------------

    if (
      [
        "Tuesday",
        "Wednesday",
        "Thursday",
        "Friday"
      ].includes(
        record.Day
      )
    ) {

      record.Shift_ID =
        "S3";

      record.Shift_Start =
        "12:30";

      record.Shift_End =
        "22:00";

      record.L1RotationApplied =
        true;

      record.L1RotationType =
        "Rotating-L1-S3-Tuesday-Friday";

    }


    // ---------------------------------------------------------
    // Saturday = S2
    // ---------------------------------------------------------

    if (
      record.Day === "Saturday"
    ) {

      record.Shift_ID =
        "S2";

      record.Shift_Start =
        "11:00";

      record.Shift_End =
        "20:30";

      record.L1RotationApplied =
        true;

      record.L1RotationType =
        "Rotating-L1-S2-Saturday";

    }

  }

}


// ---------------------------------------------------------------
// 20D. Identify weekday S1 L1.
// ---------------------------------------------------------------

const weekdayS1L1Records =
  finalRoster.filter(
    record =>

      [
        "Monday",
        "Tuesday",
        "Wednesday",
        "Thursday",
        "Friday"
      ].includes(
        record.Day
      ) &&

      String(
        record.Assignment_Level ?? ""
      )
        .trim()
        .toLowerCase() === "level1" &&

      String(
        record.Shift_ID ?? ""
      )
        .trim()
        .toUpperCase() === "S1"
  );


// ---------------------------------------------------------------
// 20E. Identify S1 L1 engineer.
// ---------------------------------------------------------------

let l1S1Engineer =
  null;

if (
  weekdayS1L1Records.length
) {

  const uniqueS1 =
    new Map();

  for (
    const record
    of weekdayS1L1Records
  ) {

    uniqueS1.set(
      normalizeMemberId(
        record.Member_ID
      ),
      record
    );

  }

  const values =
    Array.from(
      uniqueS1.values()
    );

  if (values.length === 1) {

    l1S1Engineer =
      values[0];

  }

}


const l1S2Engineer =
  rotatingL1;


// ---------------------------------------------------------------
// 20F. L1 ROTATION VALIDATION OBJECT
// ---------------------------------------------------------------

const l1RotationValidation = {

  Status:
    "CHECKED",

  S1Engineer:
    l1S1Engineer
      ? l1S1Engineer.Engineer_Name
      : null,

  S2Engineer:
    l1S2Engineer
      ? l1S2Engineer.Engineer_Name
      : null,

  SaturdayS2Engineer:
    rotatingL1
      ? rotatingL1.Engineer_Name
      : null,

  TuesdayToFridayS3Engineer:
    rotatingL1
      ? rotatingL1.Engineer_Name
      : null,

  SundayEngineers:
    finalRoster
      .filter(
        record =>
          record.Day === "Sunday" &&
          String(
            record.Assignment_Level ?? ""
          )
            .trim()
            .toLowerCase() === "level1"
      )
      .map(
        record =>
          record.Engineer_Name
      ),

  Errors: []

};


// ---------------------------------------------------------------
// RULE 1
// ---------------------------------------------------------------
// Rotating L1 must work S3 Tuesday-Friday.

if (rotatingL1) {

  const rotatingMemberId =
    normalizeMemberId(
      rotatingL1.Member_ID
    );

  for (
    const day
    of [
      "Tuesday",
      "Wednesday",
      "Thursday",
      "Friday"
    ]
  ) {

    const matching =
      finalRoster.filter(
        record =>

          record.Day === day &&

          normalizeMemberId(
            record.Member_ID
          ) === rotatingMemberId &&

          String(
            record.Assignment_Level ?? ""
          )
            .trim()
            .toLowerCase() === "level1"
      );

    if (
      matching.length !== 1 ||
      matching[0].Shift_ID !== "S3"
    ) {

      l1RotationValidation.Errors.push({

        Rule:
          "L1_ROTATING_RESOURCE_MUST_WORK_S3_TUE_FRI",

        Engineer:
          rotatingL1.Engineer_Name,

        Day:
          day,

        Expected:
          "S3",

        Actual:
          matching.length
            ? matching[0].Shift_ID
            : null

      });

    }

  }

}


// ---------------------------------------------------------------
// RULE 2
// ---------------------------------------------------------------
// Rotating L1 must work Saturday S2.

if (rotatingL1) {

  const saturdayCorrect =
    finalRoster.some(
      record =>

        record.Day === "Saturday" &&

        normalizeMemberId(
          record.Member_ID
        ) ===
        normalizeMemberId(
          rotatingL1.Member_ID
        ) &&

        String(
          record.Shift_ID
        )
          .trim()
          .toUpperCase() === "S2" &&

        String(
          record.Assignment_Level ?? ""
        )
          .trim()
          .toLowerCase() === "level1"
    );

  if (!saturdayCorrect) {

    l1RotationValidation.Errors.push({

      Rule:
        "L1_ROTATING_RESOURCE_MUST_WORK_SATURDAY_S2",

      Engineer:
        rotatingL1.Engineer_Name,

      Expected:
        "Saturday S2"

    });

  }

}


// ---------------------------------------------------------------
// RULE 3
// ---------------------------------------------------------------
// S1 L1 must not work Saturday.

if (l1S1Engineer) {

  const s1Saturday =
    finalRoster.some(
      record =>

        record.Day === "Saturday" &&

        normalizeMemberId(
          record.Member_ID
        ) ===
        normalizeMemberId(
          l1S1Engineer.Member_ID
        ) &&

        String(
          record.Assignment_Level ?? ""
        )
          .trim()
          .toLowerCase() === "level1"
    );

  if (s1Saturday) {

    l1RotationValidation.Errors.push({

      Rule:
        "L1_S1_MUST_NOT_WORK_SATURDAY",

      Engineer:
        l1S1Engineer.Engineer_Name

    });

  }

}


// ---------------------------------------------------------------
// RULE 4
// ---------------------------------------------------------------
// Only one L1 should work Saturday.

const saturdayL1Count =
  finalRoster.filter(
    record =>

      record.Day === "Saturday" &&

      String(
        record.Assignment_Level ?? ""
      )
        .trim()
        .toLowerCase() === "level1"
  ).length;


if (
  saturdayL1Count !== 1
) {

  l1RotationValidation.Errors.push({

    Rule:
      "ONLY_ONE_L1_SATURDAY",

    ActualCount:
      saturdayL1Count

  });

}


// ---------------------------------------------------------------
// RULE 5
// ---------------------------------------------------------------
// Rotating L1 must not work Sunday.

if (rotatingL1) {

  const rotatingMemberId =
    normalizeMemberId(
      rotatingL1.Member_ID
    );

  const sundayRecord =
    finalRoster.some(
      record =>

        record.Day === "Sunday" &&

        normalizeMemberId(
          record.Member_ID
        ) === rotatingMemberId &&

        String(
          record.Assignment_Level ?? ""
        )
          .trim()
          .toLowerCase() === "level1"
    );

  if (sundayRecord) {

    l1RotationValidation.Errors.push({

      Rule:
        "L1_ROTATING_RESOURCE_MUST_HAVE_SUNDAY_OFF",

      Engineer:
        rotatingL1.Engineer_Name

    });

  }

}


// ---------------------------------------------------------------
// RULE 6
// ---------------------------------------------------------------
// Rotating L1 must NOT have a Monday record.
//
// IMPORTANT:
// We do NOT create a Monday OFF record.
// We simply validate that the rotating L1 is absent.
// ---------------------------------------------------------------

if (rotatingL1) {

  const rotatingMemberId =
    normalizeMemberId(
      rotatingL1.Member_ID
    );

  const mondayRecord =
    finalRoster.some(
      record =>

        record.Day === "Monday" &&

        normalizeMemberId(
          record.Member_ID
        ) === rotatingMemberId &&

        String(
          record.Assignment_Level ?? ""
        )
          .trim()
          .toLowerCase() === "level1"
    );

  if (mondayRecord) {

    l1RotationValidation.Errors.push({

      Rule:
        "L1_ROTATING_RESOURCE_MUST_HAVE_MONDAY_OFF",

      Engineer:
        rotatingL1.Engineer_Name

    });

  }

}


// ---------------------------------------------------------------
// FINAL L1 STATUS
// ---------------------------------------------------------------

if (
  l1RotationValidation.Errors.length === 0
) {

  l1RotationValidation.Status =
    "PASS";

}
else {

  l1RotationValidation.Status =
    "FAIL";

}


// ---------------------------------------------------------------
// 21. SORT OUTPUT
// ---------------------------------------------------------------

const dayOrder = {

  Monday: 1,
  Tuesday: 2,
  Wednesday: 3,
  Thursday: 4,
  Friday: 5,
  Saturday: 6,
  Sunday: 7

};


finalRoster.sort(
  (a, b) => {

    if (
      dayOrder[a.Day] !==
      dayOrder[b.Day]
    ) {

      return (
        dayOrder[a.Day] -
        dayOrder[b.Day]
      );

    }

    return String(
      a.Shift_ID
    ).localeCompare(
      String(b.Shift_ID)
    );

  }
);


// ---------------------------------------------------------------
// 22. RETURN RESULT
// ---------------------------------------------------------------

return [

  {

    json: {

      Status:
        "ROSTER-001 OK",

      GeneratedAtUTC:
        new Date().toISOString(),

      CurrentDate:
        formatDateUTC(currentDate),

      SelectedRosterPeriod:
        selectedPeriod.label,

      Effective_From:
        selectedPeriod.startDateText,

      Effective_To:
        selectedPeriod.endDateText,

      Source:
        "OriginalRoster",

      EngineerMasterValidated:
        engineerMasterMap.size > 0,

      TotalDetectedPeriods:
        detectedPeriods.length,

      DetectedPeriods:
        detectedPeriods.map(
          p => ({

            label:
              p.label,

            startDate:
              p.startDateText,

            endDate:
              p.endDateText

          })
        ),

      TotalNormalizedRecords:
        finalRoster.length,

      WeeklyRoster:
        finalRoster,

      ValidationErrorCount:
        validationErrors.length,

      ValidationErrors:
        validationErrors,

      L1RotationValidation:
        l1RotationValidation

    }

  }

];

// ============================================================
// CODE-007 – Prepare WeeklyRoster Rows
// ============================================================
// Purpose:
// Convert ROSTER-001.WeeklyRoster[] into individual n8n items
// ready for Google Sheets → WeeklyRoster.
//
// Source:
// ROSTER-001 – Build WeeklyRoster
//
// IMPORTANT:
// This node does NOT create engineers.
// It only writes engineers that ROSTER-001 generated.
// Therefore OriginalRoster remains the authoritative source.
// ============================================================

const inputItems = $input.all();

if (!inputItems.length) {
  throw new Error(
    "CODE-007: No input received from ROSTER-001."
  );
}

// ------------------------------------------------------------
// Get ROSTER-001 output
// ------------------------------------------------------------

const source = inputItems[0].json;

if (!Array.isArray(source.WeeklyRoster)) {
  throw new Error(
    "CODE-007: WeeklyRoster array was not found in ROSTER-001 output."
  );
}

const weeklyRoster = source.WeeklyRoster;

if (weeklyRoster.length === 0) {
  throw new Error(
    "CODE-007: ROSTER-001 returned an empty WeeklyRoster."
  );
}

// ------------------------------------------------------------
// Convert each roster record into one n8n item
// ------------------------------------------------------------

const output = [];

for (const row of weeklyRoster) {

  if (!row || typeof row !== "object") {
    continue;
  }

  const engineerName = String(
    row.Engineer_Name ?? ""
  ).trim();

  const memberId = String(
    row.Member_ID ?? ""
  ).trim();

  const assignmentLevel = String(
    row.Assignment_Level ?? ""
  ).trim();

  const day = String(
    row.Day ?? ""
  ).trim();

  const shiftId = String(
    row.Shift_ID ?? ""
  ).trim();

  const effectiveFrom = String(
    row.Effective_From ?? ""
  ).trim();

  const effectiveTo = String(
    row.Effective_To ?? ""
  ).trim();

  const available = String(
    row.Available ?? "Yes"
  ).trim();

  // ----------------------------------------------------------
  // Safety validation
  // ----------------------------------------------------------

  if (!engineerName) {
    throw new Error(
      `CODE-007: Engineer_Name is missing for ${day} / ${shiftId}.`
    );
  }

  if (!memberId) {
    throw new Error(
      `CODE-007: Member_ID is missing for engineer "${engineerName}".`
    );
  }

  if (!assignmentLevel) {
    throw new Error(
      `CODE-007: Assignment_Level is missing for engineer "${engineerName}".`
    );
  }

  if (!day) {
    throw new Error(
      `CODE-007: Day is missing for engineer "${engineerName}".`
    );
  }

  if (!shiftId) {
    throw new Error(
      `CODE-007: Shift_ID is missing for engineer "${engineerName}".`
    );
  }

  if (!effectiveFrom || !effectiveTo) {
    throw new Error(
      `CODE-007: Effective date range is missing for engineer "${engineerName}".`
    );
  }

  // ----------------------------------------------------------
  // Output exactly matching WeeklyRoster columns
  // ----------------------------------------------------------

  output.push({
    json: {
      Effective_From: effectiveFrom,
      Effective_To: effectiveTo,
      Day: day,
      Shift_ID: shiftId,
      Engineer_Name: engineerName,
      Member_ID: memberId,
      Assignment_Level: assignmentLevel,
      Available: available
    }
  });
}

// ------------------------------------------------------------
// Final validation
// ------------------------------------------------------------

if (output.length === 0) {
  throw new Error(
    "CODE-007: No valid WeeklyRoster records were generated."
  );
}

return output;

